import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shippingCost } from '../src/shipping.mjs';

const us = (items) => ({ country: 'US', items });

test('AC1/AC3: flat 5 for small orders under threshold', () => {
  assert.equal(shippingCost(us([{ price: 10, qty: 1 }])), 5);
});

test('AC3: up to 3 units costs flat 5', () => {
  assert.equal(shippingCost(us([{ price: 1, qty: 3 }])), 5);
});

test('AC3: 4 units adds 2, 5 units adds 4', () => {
  assert.equal(shippingCost(us([{ price: 1, qty: 4 }])), 7);
  assert.equal(shippingCost(us([{ price: 1, qty: 5 }])), 9);
});

test('AC3: units are summed across lines', () => {
  assert.equal(shippingCost(us([{ price: 1, qty: 2 }, { price: 1, qty: 3 }])), 9);
});

test('AC1: subtotal sums price * qty across lines', () => {
  // 40*1 + 30*2 = 100 -> free
  assert.equal(shippingCost(us([{ price: 40, qty: 1 }, { price: 30, qty: 2 }])), 0);
});

test('AC2: subtotal exactly 100 ships free', () => {
  assert.equal(shippingCost(us([{ price: 100, qty: 1 }])), 0);
});

test('AC2: subtotal just under 100 is charged', () => {
  assert.equal(shippingCost(us([{ price: 99.99, qty: 1 }])), 5);
});

test('AC2: over 100 is free even with many units', () => {
  assert.equal(shippingCost(us([{ price: 50, qty: 10 }])), 0);
});

test('AC3: many units under threshold incur surcharge', () => {
  assert.equal(shippingCost(us([{ price: 1, qty: 10 }])), 5 + 7 * 2);
});

test('AC4: non-US country throws RangeError', () => {
  assert.throws(() => shippingCost({ country: 'CA', items: [{ price: 1, qty: 1 }] }), RangeError);
  assert.throws(() => shippingCost({ country: 'us', items: [{ price: 1, qty: 1 }] }), RangeError);
});

test('AC5: empty items costs 0', () => {
  assert.equal(shippingCost(us([])), 0);
});

test('AC6: negative price or qty throws RangeError', () => {
  assert.throws(() => shippingCost(us([{ price: -1, qty: 1 }])), RangeError);
  assert.throws(() => shippingCost(us([{ price: 1, qty: -1 }])), RangeError);
  assert.throws(() => shippingCost(us([{ price: 1, qty: 1 }, { price: -5, qty: 1 }])), RangeError);
});

test('order of checks: country before line validity', () => {
  assert.throws(
    () => shippingCost({ country: 'CA', items: [{ price: -1, qty: 1 }] }),
    RangeError
  );
  // Both throw RangeError; distinguish by message
  assert.throws(
    () => shippingCost({ country: 'CA', items: [{ price: -1, qty: 1 }] }),
    /country/
  );
});

test('order of checks: line validity before empty-items rule', () => {
  // An invalid line prevents any "free/zero" shortcut, even if subtotal would be huge
  assert.throws(
    () => shippingCost(us([{ price: 1000, qty: 1 }, { price: 1, qty: -1 }])),
    /line/
  );
});

test('order of checks: country checked even for empty items', () => {
  assert.throws(() => shippingCost({ country: 'CA', items: [] }), RangeError);
});

test('zero-price/zero-qty lines are valid', () => {
  assert.equal(shippingCost(us([{ price: 0, qty: 0 }])), 5);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shippingCost } from '../src/shipping.mjs';

const order = (items, country = 'US') => ({ country, items });

test('AC1: subtotal sums price * qty across items (free-shipping threshold reached via multiple lines)', () => {
  // 2*20 + 3*20 = 100 -> free
  assert.equal(shippingCost(order([{ price: 20, qty: 2 }, { price: 20, qty: 3 }])), 0);
  // 2*20 + 2*20 = 80 -> not free, 4 units
  assert.equal(shippingCost(order([{ price: 20, qty: 2 }, { price: 20, qty: 2 }])), 7);
});

test('AC2: subtotal exactly 100 ships free', () => {
  assert.equal(shippingCost(order([{ price: 100, qty: 1 }])), 0);
});

test('AC2: subtotal above 100 ships free, even with many units', () => {
  assert.equal(shippingCost(order([{ price: 150, qty: 1 }])), 0);
  assert.equal(shippingCost(order([{ price: 30, qty: 10 }])), 0);
});

test('AC2: subtotal just below 100 is not free', () => {
  assert.equal(shippingCost(order([{ price: 99.99, qty: 1 }])), 5);
});

test('AC3: flat 5 for up to 3 units', () => {
  assert.equal(shippingCost(order([{ price: 10, qty: 1 }])), 5);
  assert.equal(shippingCost(order([{ price: 10, qty: 2 }])), 5);
  assert.equal(shippingCost(order([{ price: 10, qty: 3 }])), 5);
});

test('AC3: +2 per unit beyond the third (4 units adds 2, 5 adds 4)', () => {
  assert.equal(shippingCost(order([{ price: 1, qty: 4 }])), 7);
  assert.equal(shippingCost(order([{ price: 1, qty: 5 }])), 9);
  assert.equal(shippingCost(order([{ price: 1, qty: 10 }])), 19);
});

test('AC3: units are summed across lines', () => {
  assert.equal(shippingCost(order([{ price: 1, qty: 2 }, { price: 1, qty: 2 }])), 7);
  assert.equal(shippingCost(order([{ price: 1, qty: 1 }, { price: 1, qty: 1 }, { price: 1, qty: 1 }])), 5);
});

test('AC4: non-US country throws RangeError', () => {
  assert.throws(() => shippingCost(order([{ price: 10, qty: 1 }], 'CA')), RangeError);
  assert.throws(() => shippingCost(order([{ price: 10, qty: 1 }], 'GB')), RangeError);
});

test('AC4: country match is exact (case-sensitive "US")', () => {
  assert.throws(() => shippingCost(order([{ price: 10, qty: 1 }], 'us')), RangeError);
  assert.throws(() => shippingCost(order([{ price: 10, qty: 1 }], '')), RangeError);
});

test('AC5: order with no items costs 0', () => {
  assert.equal(shippingCost(order([])), 0);
});

test('AC6: negative price throws RangeError', () => {
  assert.throws(() => shippingCost(order([{ price: -1, qty: 1 }])), RangeError);
});

test('AC6: negative qty throws RangeError', () => {
  assert.throws(() => shippingCost(order([{ price: 10, qty: -1 }])), RangeError);
});

test('AC6: a single invalid line among valid ones throws', () => {
  assert.throws(
    () => shippingCost(order([{ price: 10, qty: 1 }, { price: 10, qty: -2 }])),
    RangeError,
  );
});

test('AC6: invalid line throws even if subtotal would qualify for free shipping', () => {
  assert.throws(
    () => shippingCost(order([{ price: 500, qty: 1 }, { price: -1, qty: 1 }])),
    RangeError,
  );
});

test('AC6: zero price and zero qty are valid', () => {
  assert.equal(shippingCost(order([{ price: 0, qty: 1 }])), 5);
  assert.equal(shippingCost(order([{ price: 10, qty: 0 }])), 5);
});

test('order of checks: country is checked before line validity', () => {
  // Both invalid; either way RangeError, but country must win -> message identifies country.
  assert.throws(
    () => shippingCost(order([{ price: -1, qty: 1 }], 'CA')),
    (e) => e instanceof RangeError && /country/i.test(e.message),
  );
});

test('order of checks: line validity is checked before the empty-items rule / pricing', () => {
  assert.throws(
    () => shippingCost(order([{ price: -5, qty: 1 }])),
    (e) => e instanceof RangeError && /line/i.test(e.message),
  );
});

test('order of checks: country is checked before the empty-items rule', () => {
  assert.throws(() => shippingCost(order([], 'CA')), RangeError);
});

test('order of checks: empty-items rule precedes free-shipping pricing (result is 0 either way)', () => {
  assert.equal(shippingCost(order([])), 0);
});

