// ITEM-77 shippingCost(order) -- tests derived from spec.md (AC1-AC6), not from the implementation.
// Tier for every test: S (small, pure in-process function). Fidelity gap: none, no P/H/X doubles used.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shippingCost } from '../src/shipping.mjs';

const us = (items) => ({ country: 'US', items });

// failure mode: subtotal computed as sum of prices (ignoring qty) or of last line only.
// tier: S. criterion: ITEM-77 AC1 + AC2 (technique: partition on multi-line orders).
test('AC1: subtotal is sum of price*qty across all lines (30*2 + 40*1 = 100 -> free)', () => {
  assert.equal(shippingCost(us([{ price: 30, qty: 2 }, { price: 40, qty: 1 }])), 0);
});

// failure mode: free-shipping threshold off by one (> instead of >=).
// tier: S. criterion: ITEM-77 AC2 (technique: boundary, exactly 100).
test('AC2: subtotal exactly 100 ships free', () => {
  assert.equal(shippingCost(us([{ price: 100, qty: 1 }])), 0);
});

// failure mode: threshold too low / rounding up just below 100.
// tier: S. criterion: ITEM-77 AC2/AC3 (technique: boundary, just under 100).
test('AC2/AC3: subtotal 99.99 is not free, costs flat 5', () => {
  assert.equal(shippingCost(us([{ price: 99.99, qty: 1 }])), 5);
});

// failure mode: free shipping not applied when many units (surcharge wrongly applied to free orders).
// tier: S. criterion: ITEM-77 AC2 (technique: interaction of two rules).
test('AC2: free shipping wins over the extra-unit surcharge (10 units, subtotal 100 -> 0)', () => {
  assert.equal(shippingCost(us([{ price: 10, qty: 10 }])), 0);
});

// failure mode: wrong surcharge threshold or rate. Each unit-count class must show red once.
// tier: S. criterion: ITEM-77 AC3 (technique: boundary at 3/4 units, partition, parameterized).
for (const [units, expected] of [[1, 5], [3, 5], [4, 7], [5, 9], [10, 19]]) {
  test(`AC3: ${units} unit(s) under the free threshold cost ${expected}`, () => {
    assert.equal(shippingCost(us([{ price: 1, qty: units }])), expected);
  });
}

// failure mode: units counted as number of lines instead of sum of qty.
// tier: S. criterion: ITEM-77 AC3 (technique: partition, multiple lines).
test('AC3: units are summed across lines (2 + 2 = 4 units -> 7)', () => {
  assert.equal(shippingCost(us([{ price: 1, qty: 2 }, { price: 1, qty: 2 }])), 7);
});

// failure mode: non-US country accepted, or wrong error type.
// tier: S. criterion: ITEM-77 AC4 (technique: negative input, partition of country strings).
for (const country of ['CA', 'GB', 'us', 'USA', '']) {
  test(`AC4: country ${JSON.stringify(country)} throws RangeError`, () => {
    assert.throws(
      () => shippingCost({ country, items: [{ price: 10, qty: 1 }] }),
      RangeError,
    );
  });
}

// failure mode: empty-items shortcut runs before the country check.
// tier: S. criterion: ITEM-77 AC4 + order of checks (technique: check-ordering).
test('order: unsupported country with empty items still throws RangeError (country before AC5)', () => {
  assert.throws(() => shippingCost({ country: 'CA', items: [] }), RangeError);
});

// failure mode: empty order priced as a flat 5 (or throws).
// tier: S. criterion: ITEM-77 AC5.
test('AC5: US order with no items costs 0', () => {
  assert.equal(shippingCost(us([])), 0);
});

// failure mode: negative price accepted.
// tier: S. criterion: ITEM-77 AC6 (technique: negative input).
test('AC6: negative price throws RangeError', () => {
  assert.throws(() => shippingCost(us([{ price: -1, qty: 1 }])), RangeError);
});

// failure mode: negative qty accepted.
// tier: S. criterion: ITEM-77 AC6 (technique: negative input).
test('AC6: negative qty throws RangeError', () => {
  assert.throws(() => shippingCost(us([{ price: 10, qty: -1 }])), RangeError);
});

// failure mode: invalid line masked by free-shipping subtotal (validation after pricing)
// or by another valid line.
// tier: S. criterion: ITEM-77 AC6 + order of checks (validation precedes pricing).
test('AC6: an invalid line throws even when other lines would make the order free', () => {
  assert.throws(
    () => shippingCost(us([{ price: 500, qty: 1 }, { price: -1, qty: 1 }])),
    RangeError,
  );
});

// failure mode: zero treated as negative (boundary off by one in validation).
// tier: S. criterion: ITEM-77 AC6 (technique: boundary at 0). Non-empty items, so AC5 does not apply.
test('AC6 boundary: price 0 is valid (not negative) and costs flat 5', () => {
  assert.equal(shippingCost(us([{ price: 0, qty: 1 }])), 5);
});

test('AC6 boundary: qty 0 is valid (not negative); non-empty order, 0 units, costs flat 5', () => {
  assert.equal(shippingCost(us([{ price: 10, qty: 0 }])), 5);
});

// ITEM-77 shippingCost(order) — tests derived from spec.md (AC1-AC6), not from the implementation.
// Tier: S (small, pure function, no I/O). Fidelity gap: none (P/H/X not used; no fakes or I/O).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shippingCost } from '../src/shipping.mjs';

const us = (items) => ({ country: 'US', items });
const line = (price, qty) => ({ price, qty });

// Failure mode: subtotal computed wrongly (e.g. sum of prices, or price+qty). Item ITEM-77, AC1 (+AC2 consequence).
// Technique: partitions. Subtotal drives the free threshold; 2 lines of 30x2 = 60 (<100) vs 20+... distinguishes sum(price*qty).
test('AC1: subtotal is sum of price*qty across lines (not sum of prices)', () => {
  // sum(price*qty) = 50*1 + 25*2 = 100 -> free. sum(price)=75 would wrongly charge.
  assert.equal(shippingCost(us([line(50, 1), line(25, 2)])), 0);
  // sum(price*qty) = 10*3 + 20*1 = 50 -> charged: 5 + 2*(4-3) = 7.
  assert.equal(shippingCost(us([line(10, 3), line(20, 1)])), 7);
});

// Failure mode: threshold off-by-one (> instead of >=) or wrong cutoff. Item ITEM-77, AC2.
// Technique: boundary values (99.99 / 100 / 100.01).
test('AC2: subtotal exactly 100 ships free; just below pays; just above is free', () => {
  assert.equal(shippingCost(us([line(100, 1)])), 0);
  assert.equal(shippingCost(us([line(99.99, 1)])), 5);
  assert.equal(shippingCost(us([line(100.01, 1)])), 0);
});

// Failure mode: per-unit surcharge applied to free orders. Item ITEM-77, AC2 vs AC3.
test('AC2: free shipping is 0 regardless of unit count', () => {
  assert.equal(shippingCost(us([line(20, 10)])), 0); // subtotal 200, 10 units
});

// Failure mode: wrong flat rate / surcharge threshold / slope. Item ITEM-77, AC3.
// Technique: boundary on units (1, 3, 4, 5, 10), each equivalence class asserted separately.
test('AC3: flat 5 for up to three units', () => {
  assert.equal(shippingCost(us([line(1, 1)])), 5);
  assert.equal(shippingCost(us([line(1, 3)])), 5);
});

test('AC3: +2 for every unit beyond the third (4 units adds 2, 5 adds 4, 10 adds 14)', () => {
  assert.equal(shippingCost(us([line(1, 4)])), 7);
  assert.equal(shippingCost(us([line(1, 5)])), 9);
  assert.equal(shippingCost(us([line(1, 10)])), 19);
});

// Failure mode: units counted per line instead of summed across lines. Item ITEM-77, AC3.
test('AC3: units are summed across lines before the third-unit cutoff', () => {
  // 2 + 2 = 4 units -> 5 + 2 = 7 (per-line counting would give 5).
  assert.equal(shippingCost(us([line(1, 2), line(1, 2)])), 7);
});

// Failure mode: non-US countries accepted, or wrong error type. Item ITEM-77, AC4.
// Technique: negative/adversarial input (case variants, empty, lookalike).
test('AC4: non-"US" country throws RangeError', () => {
  for (const country of ['CA', 'GB', '', 'us', 'USA', ' US']) {
    assert.throws(
      () => shippingCost({ country, items: [line(10, 1)] }),
      RangeError,
      `country ${JSON.stringify(country)} must throw RangeError`,
    );
  }
});

// Failure mode: country check skipped when order is empty (AC5 short-circuits AC4). Item ITEM-77, order of checks.
test('AC4 precedes AC5: unsupported country with no items throws RangeError, not 0', () => {
  assert.throws(() => shippingCost({ country: 'CA', items: [] }), RangeError);
});

// Failure mode: empty order priced (flat 5) instead of 0. Item ITEM-77, AC5.
test('AC5: US order with no items costs 0', () => {
  assert.equal(shippingCost(us([])), 0);
});

// Failure mode: negative price/qty not rejected, or wrong error type. Item ITEM-77, AC6.
// Technique: partitions (negative price, negative qty, bad line among good ones).
test('AC6: negative price throws RangeError', () => {
  assert.throws(() => shippingCost(us([line(-1, 1)])), RangeError);
});

test('AC6: negative qty throws RangeError', () => {
  assert.throws(() => shippingCost(us([line(10, -1)])), RangeError);
});

test('AC6: one invalid line among valid lines still throws RangeError', () => {
  assert.throws(() => shippingCost(us([line(10, 1), line(5, -2), line(3, 1)])), RangeError);
});

// Failure mode: invalid line masked because subtotal still >= 100 (free shortcut before validation). Item ITEM-77, AC6 ordering.
test('AC6: invalid line throws even when remaining subtotal would ship free', () => {
  assert.throws(() => shippingCost(us([line(500, 1), line(10, -1)])), RangeError);
});

// Failure mode: zero treated as invalid (over-strict AC6). Item ITEM-77, AC6 boundary.
test('AC6 boundary: zero price is valid (only negatives rejected)', () => {
  assert.equal(shippingCost(us([line(0, 1)])), 5);
});

// Tests for ITEM-77 shippingCost(order), derived from spec.md (AC1-AC6) and the
// exported interface only. Tier: S (in-process, no I/O).
// Fidelity-gap statement (P/H/X): n/a, tier S has no production-fidelity,
// hardware, or cross-process surface; pure function over plain data.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shippingCost } from '../src/shipping.mjs';

const us = (items) => ({ country: 'US', items });

// Failure mode: subtotal ignores qty or drops lines (AC1), so the free/paid decision flips.
// Item ITEM-77, criterion AC1 (+AC2/AC3 as the observable effect). Tier S.
test('AC1: subtotal is sum of price*qty across all lines', () => {
  // 30*2 + 50*1 = 110 -> free. Sum-of-prices (80) or first-line-only would charge.
  assert.equal(shippingCost(us([{ price: 30, qty: 2 }, { price: 50, qty: 1 }])), 0);
  // 30*2 + 39*1 = 99, 3 units -> 5. Distinguishes from a wrong total >= 100.
  assert.equal(shippingCost(us([{ price: 30, qty: 2 }, { price: 39, qty: 1 }])), 5);
});

// Failure mode: free-shipping threshold off by one (> instead of >=) (AC2).
// Boundary analysis: just below, exactly at, just above 100. Item ITEM-77, AC2. Tier S.
test('AC2: subtotal >= 100 ships free, exactly 100 included (boundary)', () => {
  assert.equal(shippingCost(us([{ price: 99.99, qty: 1 }])), 5);
  assert.equal(shippingCost(us([{ price: 100, qty: 1 }])), 0);
  assert.equal(shippingCost(us([{ price: 100.01, qty: 1 }])), 0);
});

// Failure mode: free shipping still adds the per-unit surcharge (AC2 vs AC3 precedence).
// Item ITEM-77, AC2/AC3. Tier S.
test('AC2: free shipping overrides the extra-unit surcharge', () => {
  assert.equal(shippingCost(us([{ price: 10, qty: 10 }])), 0); // 100, 10 units
});

// Failure mode: surcharge miscounted (threshold at 3 vs 4, rate, or per-line instead
// of total units) (AC3). Partition/boundary on units; one failure mode, parameterized.
// Item ITEM-77, AC3. Tier S.
test('AC3: flat 5 plus 2 per unit beyond the third', () => {
  const cases = [
    [1, 5],
    [3, 5], // boundary: third unit adds nothing
    [4, 7], // boundary: 4 units adds 2
    [5, 9], // 5 units adds 4
    [10, 19], // 5 + 2*7
  ];
  for (const [units, expected] of cases) {
    assert.equal(shippingCost(us([{ price: 1, qty: units }])), expected, `${units} units`);
  }
});

// Failure mode: units counted per line instead of summed across lines (AC3).
// Item ITEM-77, AC3. Tier S.
test('AC3: units are summed across lines before the third-unit threshold', () => {
  // 2 + 2 = 4 units, subtotal 4 -> 5 + 2 = 7. Per-line counting would give 5.
  assert.equal(shippingCost(us([{ price: 1, qty: 2 }, { price: 1, qty: 2 }])), 7);
});

// Failure mode: zero-valued line wrongly rejected or treated as empty order (AC6/AC5 boundary).
// Only NEGATIVE values are invalid; an order with items is not "no items". Item ITEM-77, AC5/AC6. Tier S.
test('AC5/AC6 boundary: zero price and zero qty are valid, non-empty orders', () => {
  assert.equal(shippingCost(us([{ price: 0, qty: 1 }])), 5); // 1 unit, subtotal 0
  assert.equal(shippingCost(us([{ price: 5, qty: 0 }])), 5); // 0 units, subtotal 0
});

// Failure mode: non-US country accepted or wrong error type (AC4).
// Negative/adversarial input: other country, case variant, empty, missing. Item ITEM-77, AC4. Tier S.
test('AC4: any country other than "US" throws RangeError', () => {
  const items = [{ price: 10, qty: 1 }];
  for (const country of ['CA', 'us', 'USA', '', undefined]) {
    assert.throws(() => shippingCost({ country, items }), RangeError, `country=${String(country)}`);
  }
});

// Failure mode: country check skipped when order is empty (AC4 precedes AC5 in check order).
// Item ITEM-77, AC4/AC5 ordering. Tier S.
test('AC4 before AC5: unsupported country with no items throws, not 0', () => {
  assert.throws(() => shippingCost({ country: 'CA', items: [] }), RangeError);
});

// Failure mode: empty order priced as flat 5 instead of 0 (AC5). Item ITEM-77, AC5. Tier S.
test('AC5: US order with no items costs 0', () => {
  assert.equal(shippingCost(us([])), 0);
});

// Failure mode: negative price/qty accepted or wrong error type (AC6).
// Partition: negative price, negative qty, invalid line among valid ones. Item ITEM-77, AC6. Tier S.
test('AC6: a line with negative price or negative qty throws RangeError', () => {
  assert.throws(() => shippingCost(us([{ price: -1, qty: 1 }])), RangeError);
  assert.throws(() => shippingCost(us([{ price: 1, qty: -1 }])), RangeError);
  assert.throws(
    () => shippingCost(us([{ price: 50, qty: 1 }, { price: 10, qty: -2 }])),
    RangeError,
  );
});

// Failure mode: line validity checked after pricing, so a free-shipping subtotal masks
// an invalid line (AC6 precedes pricing). Item ITEM-77, AC6 ordering. Tier S.
test('AC6 before pricing: invalid line throws even when subtotal would ship free', () => {
  // Valid line alone is 200 (free); the negative-price line must still throw.
  assert.throws(
    () => shippingCost(us([{ price: 200, qty: 1 }, { price: -5, qty: 1 }])),
    RangeError,
  );
});

// Failure mode: line validity checked before country (AC4 precedes AC6 in check order).
// Both raise RangeError, so assert on the message-independent type AND that the
// country-invalid + valid-lines case still throws (country check is not bypassed).
// Item ITEM-77, AC4/AC6 ordering. Tier S.
test('AC4 before AC6: unsupported country with an invalid line throws RangeError', () => {
  assert.throws(
    () => shippingCost({ country: 'CA', items: [{ price: -1, qty: 1 }] }),
    RangeError,
  );
});
